
# Catch the Diamonds! — OpenGL Python (PyOpenGL + GLUT)
# Requirements:
#   pip install PyOpenGL PyOpenGL_accelerate
#
# Run:
#   python catch_the_diamonds.py
#
# Notes:
# - Uses only GL_POINTS to draw, via our Midpoint Line algorithm (8-way symmetry).
# - Buttons: Left (Restart), Middle (Play/Pause), Right (Quit).
# - Diamond falls from top; catch with the bowl-shaped catcher (rectangle outline).
# - AABB collision detection.
# - No glutTimerFunc(); uses delta-time in idle callback.
# - Prints score/events to the console.
#
# Author: Generated by ChatGPT for user requirements.

import sys
import time
import random
from math import fabs

try:
    from OpenGL.GL import *
    from OpenGL.GLU import *
    from OpenGL.GLUT import *
except Exception as e:
    print("PyOpenGL is required. Install with: pip install PyOpenGL PyOpenGL_accelerate")
    raise

# -----------------------------
# Window / World Setup
# -----------------------------
WIDTH, HEIGHT = 900, 640

# -----------------------------
# Game State
# -----------------------------
score = 0
is_paused = False
game_over = False

# Catcher (a rectangle outline, drawn with 4 midpoint lines)
catcher_width = 120
catcher_height = 18  # thin
catcher_speed = 420.0  # px/sec (delta-time based)
catcher_color_live = (1.0, 1.0, 1.0)  # white
catcher_color_dead = (1.0, 0.2, 0.2)  # red
catcher_x = WIDTH // 2 - catcher_width // 2
catcher_y = 80  # near bottom

# Diamond (a rhombus, drawn with 4 midpoint lines; its AABB used for collision)
diamond_size = 36
diamond_x = WIDTH // 2
diamond_y = HEIGHT - 80
diamond_speed = 160.0  # base fall speed
diamond_accel = 8.0    # small acceleration per second
diamond_color = (1.0, 1.0, 0.0)  # will be randomized each spawn

# Random bright colors to choose from for diamond
BRIGHT_COLORS = [
    (1.0, 0.2, 0.2),   # bright red
    (1.0, 0.5, 0.2),   # orange
    (1.0, 1.0, 0.0),   # yellow
    (0.4, 1.0, 0.4),   # lime
    (0.2, 1.0, 1.0),   # cyan/teal
    (0.4, 0.6, 1.0),   # sky
    (1.0, 0.4, 1.0),   # magenta
]

# UI Buttons (top row)
BTN_Y1, BTN_Y2 = HEIGHT - 80, HEIGHT - 20
BTN_W, BTN_H = 120, 50
BTN_GAP = 36
BTN_X1 = 40
BTN_X2 = BTN_X1 + BTN_W + BTN_GAP
BTN_X3 = BTN_X2 + BTN_W + BTN_GAP

# Colors for buttons
TEAL = (0.0, 0.85, 0.8)
AMBER = (1.0, 0.65, 0.0)
RED = (0.9, 0.2, 0.2)
UI_WHITE = (1.0, 1.0, 1.0)
UI_GREY = (0.7, 0.7, 0.7)

last_time = time.time()
left_pressed = False
right_pressed = False

# -----------------------------
# Midpoint Line Drawing — 8-way symmetry
# -----------------------------

def plot_point(x, y):
    # Plot a single "pixel" as a GL point
    glVertex2i(int(x), int(y))

def find_zone(x1, y1, x2, y2):
    dx = x2 - x1
    dy = y2 - y1
    adx = abs(dx)
    ady = abs(dy)

    if adx >= ady:
        if dx >= 0 and dy >= 0:
            return 0
        if dx < 0 and dy >= 0:
            return 3
        if dx < 0 and dy < 0:
            return 4
        if dx >= 0 and dy < 0:
            return 7
    else:
        if dx >= 0 and dy >= 0:
            return 1
        if dx < 0 and dy >= 0:
            return 2
        if dx < 0 and dy < 0:
            return 5
        if dx >= 0 and dy < 0:
            return 6
    return 0

def to_zone0(x, y, zone):
    if zone == 0:
        return x, y
    elif zone == 1:
        return y, x
    elif zone == 2:
        return y, -x
    elif zone == 3:
        return -x, y
    elif zone == 4:
        return -x, -y
    elif zone == 5:
        return -y, -x
    elif zone == 6:
        return -y, x
    elif zone == 7:
        return x, -y
    return x, y

def from_zone0(x, y, zone):
    if zone == 0:
        return x, y
    elif zone == 1:
        return y, x
    elif zone == 2:
        return -y, x
    elif zone == 3:
        return -x, y
    elif zone == 4:
        return -x, -y
    elif zone == 5:
        return -y, -x
    elif zone == 6:
        return y, -x
    elif zone == 7:
        return x, -y
    return x, y

def draw_line_zone0(x1, y1, x2, y2):
    # Assumes x1 <= x2
    dx = x2 - x1
    dy = y2 - y1
    d = 2 * dy - dx
    incE = 2 * dy
    incNE = 2 * (dy - dx)
    y = y1

    x = x1
    while x <= x2:
        plot_point(x, y)
        if d > 0:
            y += 1
            d += incNE
        else:
            d += incE
        x += 1

def draw_line(x1, y1, x2, y2):
    # Generalized Midpoint line in any of 8 zones; plots with GL_POINTS.
    zone = find_zone(x1, y1, x2, y2)
    # Convert endpoints to zone 0
    zx1, zy1 = to_zone0(x1, y1, zone)
    zx2, zy2 = to_zone0(x2, y2, zone)
    # Ensure left-to-right for zone 0 algo
    if zx2 < zx1:
        zx1, zx2 = zx2, zx1
        zy1, zy2 = zy2, zy1

    # Compute points in zone 0, map back and plot
    dx = zx2 - zx1
    dy = zy2 - zy1
    d = 2 * dy - dx
    incE = 2 * dy
    incNE = 2 * (dy - dx)
    y = zy1
    x = zx1

    glBegin(GL_POINTS)
    while x <= zx2:
        ox, oy = from_zone0(x, y, zone)
        plot_point(ox, oy)
        if d > 0:
            y += 1
            d += incNE
        else:
            d += incE
        x += 1
    glEnd()

# -----------------------------
# Higher-Level Shapes Using Lines
# -----------------------------

def draw_rect_outline(x, y, w, h):
    # rectangle outline with 4 lines
    draw_line(x, y, x + w, y)             # bottom
    draw_line(x + w, y, x + w, y + h)     # right
    draw_line(x + w, y + h, x, y + h)     # top
    draw_line(x, y + h, x, y)             # left

def draw_arrow_left(x1, y1, x2, y2, color):
    # Draw a left arrow inside the bounding box (x1,y1)-(x2,y2)
    glColor3f(*color)
    # outline: rectangular body + triangular head
    w = x2 - x1
    h = y2 - y1
    cx = (x1 + x2) // 2
    midy = (y1 + y2) // 2
    # Arrow head points
    head_left = (x1 + w * 0.18, midy)
    head_top = (x1 + w * 0.45, y2 - h * 0.15)
    head_bot = (x1 + w * 0.45, y1 + h * 0.15)
    # Body rectangle
    body_left = int(x1 + w * 0.42)
    body_right = int(x2 - w * 0.15)
    body_top = int(y2 - h * 0.25)
    body_bot = int(y1 + h * 0.25)

    # Head (triangle outline)
    draw_line(int(head_left[0]), int(head_left[1]), int(head_top[0]), int(head_top[1]))
    draw_line(int(head_left[0]), int(head_left[1]), int(head_bot[0]), int(head_bot[1]))
    draw_line(int(head_top[0]), int(head_top[1]), int(head_bot[0]), int(head_bot[1]))

    # Body (rectangle outline)
    draw_rect_outline(body_left, body_bot, body_right - body_left, body_top - body_bot)

def draw_play_pause(x1, y1, x2, y2, is_playing, color):
    glColor3f(*color)
    w = x2 - x1
    h = y2 - y1
    if is_playing:
        # Pause icon: two vertical bars
        pad = int(w * 0.2)
        bar_w = int(w * 0.15)
        yb = y1 + int(h * 0.15)
        yt = y2 - int(h * 0.15)
        # Left bar
        draw_rect_outline(x1 + pad, yb, bar_w, yt - yb)
        # Right bar
        draw_rect_outline(x2 - pad - bar_w, yb, bar_w, yt - yb)
    else:
        # Play icon: triangle pointing right
        p1 = (x1 + int(w * 0.3), y1 + int(h * 0.15))
        p2 = (x1 + int(w * 0.3), y2 - int(h * 0.15))
        p3 = (x2 - int(w * 0.25), y1 + h // 2)
        draw_line(p1[0], p1[1], p2[0], p2[1])
        draw_line(p2[0], p2[1], p3[0], p3[1])
        draw_line(p3[0], p3[1], p1[0], p1[1])

def draw_cross(x1, y1, x2, y2, color):
    glColor3f(*color)
    pad = int(min(x2 - x1, y2 - y1) * 0.22)
    draw_line(x1 + pad, y1 + pad, x2 - pad, y2 - pad)
    draw_line(x1 + pad, y2 - pad, x2 - pad, y1 + pad)

def draw_diamond(cx, cy, size, color):
    glColor3f(*color)
    half = size // 2
    # diamond points
    top = (cx, cy + half)
    right = (cx + half, cy)
    bottom = (cx, cy - half)
    left = (cx - half, cy)
    # 4 lines
    draw_line(top[0], top[1], right[0], right[1])
    draw_line(right[0], right[1], bottom[0], bottom[1])
    draw_line(bottom[0], bottom[1], left[0], left[1])
    draw_line(left[0], left[1], top[0], top[1])

def draw_catcher(x, y, w, h, color):
    glColor3f(*color)
    # a simple rectangle "bowl" outline
    draw_rect_outline(int(x), int(y), int(w), int(h))

# -----------------------------
# AABB Collision
# -----------------------------

def aabb_intersect(a, b):
    return (a['x'] < b['x'] + b['w'] and
            a['x'] + a['w'] > b['x'] and
            a['y'] < b['y'] + b['h'] and
            a['y'] + a['h'] > b['y'])

def diamond_aabb(cx, cy, size):
    half = size // 2
    return {'x': cx - half, 'y': cy - half, 'w': size, 'h': size}

def catcher_aabb(x, y, w, h):
    return {'x': x, 'y': y, 'w': w, 'h': h}

# -----------------------------
# Game Logic
# -----------------------------

def reset_game():
    global score, is_paused, game_over
    global diamond_x, diamond_y, diamond_speed, diamond_color
    global catcher_x

    score = 0
    is_paused = False
    game_over = False
    diamond_x = random.randint(80, WIDTH - 80)
    diamond_y = HEIGHT - 80
    diamond_speed = 160.0
    diamond_color = random.choice(BRIGHT_COLORS)
    catcher_x = WIDTH // 2 - catcher_width // 2
    print("Starting Over")

def spawn_new_diamond():
    global diamond_x, diamond_y, diamond_color
    diamond_x = random.randint(80, WIDTH - 80)
    diamond_y = HEIGHT - 80
    diamond_color = random.choice(BRIGHT_COLORS)

def update(dt):
    global diamond_y, diamond_speed, score, game_over

    if is_paused or game_over:
        return

    # accelerate slowly
    diamond_speed += diamond_accel * dt

    # fall
    diamond_y -= diamond_speed * dt

    # AABB collision (diamond & catcher)
    dbox = diamond_aabb(diamond_x, int(diamond_y), diamond_size)
    cbox = catcher_aabb(int(catcher_x), int(catcher_y), catcher_width, catcher_height)

    if aabb_intersect(dbox, cbox):
        score += 1
        print(f"Score: {score}")
        spawn_new_diamond()

    # Missed?
    if diamond_y + (diamond_size // 2) < 0:
        game_over_state()

def game_over_state():
    global game_over
    if not game_over:
        game_over = True
        print(f"Game Over | Final Score: {score}")

# -----------------------------
# Input Handling
# -----------------------------

def keyboard(key, x, y):
    global left_pressed, right_pressed
    if key == b'\x1b':  # ESC quits
        goodbye_and_quit()
    # no-op; use special keys for arrows

def keyboard_up(key, x, y):
    pass

def special_key(key, x, y):
    # Arrow keys
    # Disable movement if paused or game over
    global catcher_x
    if is_paused or game_over:
        return
    if key == GLUT_KEY_LEFT:
        catcher_x -= catcher_speed * 0.016 # small step on discrete press
    elif key == GLUT_KEY_RIGHT:
        catcher_x += catcher_speed * 0.016
    clamp_catcher()

def special_up(key, x, y):
    pass

def mouse(button, state, mx, my):
    # GLUT reports y from top-left? We set ortho (0..W, 0..H) with bottom-left origin,
    # but GLUT mouse gives origin at top-left. Convert:
    my_converted = HEIGHT - my

    if button == GLUT_LEFT_BUTTON and state == GLUT_DOWN:
        if point_in_rect(mx, my_converted, BTN_X1, BTN_Y1, BTN_W, BTN_H):
            # Restart
            reset_game()
        elif point_in_rect(mx, my_converted, BTN_X2, BTN_Y1, BTN_W, BTN_H):
            # Play/Pause toggle
            toggle_pause()
        elif point_in_rect(mx, my_converted, BTN_X3, BTN_Y1, BTN_W, BTN_H):
            # Quit
            goodbye_and_quit()

def point_in_rect(px, py, rx, ry, rw, rh):
    return (px >= rx and px <= rx + rw and py >= ry and py <= ry + rh)

def toggle_pause():
    global is_paused
    is_paused = not is_paused

def goodbye_and_quit():
    print(f"Goodbye | Score: {score}")
    try:
        glutLeaveMainLoop()
    except Exception:
        # Fallback if leave main loop unsupported
        sys.exit(0)

def clamp_catcher():
    global catcher_x
    if catcher_x < 10:
        catcher_x = 10
    if catcher_x + catcher_width > WIDTH - 10:
        catcher_x = WIDTH - 10 - catcher_width

# -----------------------------
# Render
# -----------------------------

def draw_button(x, y, w, h, border_color=UI_GREY):
    glColor3f(*border_color)
    draw_rect_outline(x, y, w, h)

def display():
    glClear(GL_COLOR_BUFFER_BIT)

    # Draw UI Buttons
    draw_button(BTN_X1, BTN_Y1, BTN_W, BTN_H)
    draw_button(BTN_X2, BTN_Y1, BTN_W, BTN_H)
    draw_button(BTN_X3, BTN_Y1, BTN_W, BTN_H)

    # Icons
    draw_arrow_left(BTN_X1, BTN_Y1, BTN_X1 + BTN_W, BTN_Y1 + BTN_H, TEAL)
    draw_play_pause(BTN_X2, BTN_Y1, BTN_X2 + BTN_W, BTN_Y1 + BTN_H, is_playing=not is_paused and not game_over, color=AMBER)
    draw_cross(BTN_X3, BTN_Y1, BTN_X3 + BTN_W, BTN_Y1 + BTN_H, RED)

    # Draw Diamond
    draw_diamond(int(diamond_x), int(diamond_y), diamond_size, diamond_color)

    # Draw Catcher
    ccolor = catcher_color_dead if game_over else catcher_color_live
    draw_catcher(int(catcher_x), int(catcher_y), catcher_width, catcher_height, ccolor)

    glutSwapBuffers()

def idle():
    global last_time
    now = time.time()
    dt = now - last_time
    last_time = now
    update(dt)
    glutPostRedisplay()

# -----------------------------
# Init
# -----------------------------

def init_gl():
    glClearColor(0.06, 0.06, 0.08, 1.0)  # dark background
    glMatrixMode(GL_PROJECTION)
    glLoadIdentity()
    gluOrtho2D(0, WIDTH, 0, HEIGHT)
    glMatrixMode(GL_MODELVIEW)
    glLoadIdentity()
    glPointSize(1.0)  # use 1px points (default)

def main():
    random.seed(int(time.time()))
    glutInit(sys.argv)
    glutInitDisplayMode(GLUT_DOUBLE | GLUT_RGB)
    glutInitWindowSize(WIDTH, HEIGHT)
    glutInitWindowPosition(100, 50)
    glutCreateWindow(b"Catch the Diamonds! - Midpoint Line Drawing (GL_POINTS)")

    init_gl()
    reset_game()

    glutDisplayFunc(display)
    glutIdleFunc(idle)
    glutKeyboardFunc(keyboard)
    glutKeyboardUpFunc(keyboard_up)
    glutSpecialFunc(special_key)
    glutSpecialUpFunc(special_up)
    glutMouseFunc(mouse)

    try:
        glutMainLoop()
    except SystemExit:
        pass

if __name__ == "__main__":
    main()
